import React, { useState } from "react";
import "./userprofile.css";

const UserProfile = () => {
  const [formData, setFormData] = useState({
    firstName: "",
    lastName: "",
    email: "",
  });

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value,
    });
  };

  const handleVerify = () => {
    const email = formData.email.trim();

    const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

    if (email === "") {
      alert("Please enter your email");
      return;
    }

    if (!emailPattern.test(email)) {
      alert("Please enter a valid email address");
      return;
    }

    alert("Email verification sent!");
  };

  return (
    <div className="profile-page">

      {/* Header */}

      <div className="page-header">

        <div>
          <h1>Create your user profile</h1>
          <p>Complete your profile details to continue</p>
        </div>

      </div>


      {/* Main Content */}

      <div className="content-area">

        {/* Profile Steps */}

        <div className="steps-card">

          <h2>Profile setup</h2>

          <p className="steps-description">
            Complete the following steps
          </p>

          <div className="steps-list">

            <div className="dashboard-step active">
              <span className="step-number">01</span>
              <span>Create Profile</span>
            </div>

            <div className="dashboard-step">
              <span className="step-number">02</span>
              <span>Aadhaar & PAN Details</span>
            </div>

            <div className="dashboard-step">
              <span className="step-number">03</span>
              <span>GST Details</span>
            </div>

            <div className="dashboard-step">
              <span className="step-number">04</span>
              <span>Bank Details</span>
            </div>

            <div className="dashboard-step">
              <span className="step-number">05</span>
              <span>Agreement</span>
            </div>

          </div>

        </div>


        {/* Form */}

        <div className="form-card">

          <div className="form-header">

            <h2>Personal information</h2>

            <p>
              Enter your basic profile details
            </p>

          </div>


          <form>

            {/* First and Last Name */}

            <div className="form-row">

              <div className="input-group">

                <label>First name</label>

                <input
                  type="text"
                  name="firstName"
                  placeholder="e.g Subash"
                  value={formData.firstName}
                  onChange={handleChange}
                />

              </div>


              <div className="input-group">

                <label>Last name</label>

                <input
                  type="text"
                  name="lastName"
                  placeholder="e.g ebin"
                  value={formData.lastName}
                  onChange={handleChange}
                />

              </div>

            </div>


            {/* Email */}

            <div className="email-group">

              <label>Email</label>

              <div className="email-input-row">

                <input
                  type="email"
                  name="email"
                  placeholder="e.g you@examplemail.com"
                  value={formData.email}
                  onChange={handleChange}
                />

                <button
                  type="button"
                  onClick={handleVerify}
                >
                  Verify
                </button>

              </div>

            </div>


            {/* Save */}

            <div className="form-footer">

              <button
                type="button"
                className="save-button"
              >
                Save Profile
              </button>

            </div>

          </form>

        </div>

      </div>

    </div>
  );
};

export default UserProfile;
